def parse(self, text: str) -> Dict[str, List[Any]]:
    # Try to find XML string within triple backticks
    match = re.search(r"```(xml)?(.*)```", text, re.DOTALL)
    if match is not None:
        # If match found, use the content within the backticks
        text = match.group(2)
    encoding_match = self.encoding_matcher.search(text)
    if encoding_match:
        text = encoding_match.group(2)

    text = text.strip()
    try:
        root = ET.fromstring(text)
        return self._root_to_dict(root)

    except ET.ParseError as e:
        msg = f"Failed to parse XML format from completion {text}. Got: {e}"
        raise OutputParserException(msg, llm_output=text) from e

def clone(
    self,
    pdf_dest: PdfWriterProtocol,
    force_duplicate: bool = False,
    ignore_fields: Optional[Sequence[Union[str, int]]] = (),
) -> "DictionaryObject":
    """Clone object into pdf_dest."""
    try:
        if self.indirect_reference.pdf == pdf_dest and not force_duplicate:  # type: ignore
            return self
    except Exception:
        pass

    d__ = cast(
        "DictionaryObject",
        self._reference_clone(self.__class__(), pdf_dest, force_duplicate),
    )
    if ignore_fields is None:
        ignore_fields = []
    if len(d__.keys()) == 0:
        d__._clone(self, pdf_dest, force_duplicate, ignore_fields)
    return d__

