    threads: List[Thread] = []
    for _ in range(count):
        t = Thread(
            target=silent_create_user,
            args=(UserRequest(name=user_name, password=password),),
        )
        threads.append(t)
    for t in threads:
        t.start()
    for t in threads:
        t.join()

    users = clean_client.zen_store.list_users(
        user_filter_model=UserFilter(name=user_name)
    )
    assert users.total == 1

