def compat_shlex_quote(s):
    import re
    return s if re.match(r'^[-_\w./]+$', s) else '"%s"' % s.replace('"', '\\"')

def get_result_from_sqldb(
    db: SQLDatabase, cmd: str
) -> Union[str, List[Dict[str, Any]], Dict[str, Any]]:
    result = db._execute(cmd, fetch="all")  # type: ignore
    if isinstance(result, list):
        return [{k: _try_eval(v) for k, v in dict(d._asdict()).items()} for d in result]
    else:
        return {
            k: _try_eval(v) for k, v in dict(result._asdict()).items()  # type: ignore
        }

def __render_string(self, value):
    orig = last = value
    max_recursion = self.__dict__.get('jinja_max_recursion', 5)
    for _ in range(max_recursion):
        template = jinja2.Template(value, keep_trailing_newline=True)
        value = _to_native(template.render(self.__dict__))
        if value == last:
            return value
        last = value
    raise ValueError("too deep jinja re-evaluation on '{}'".format(orig))

