def from_data(*, data: oai.Operation, path: str, method: str, tag: str) -> Union[Endpoint, ParseError]:
    """ Construct an endpoint from the OpenAPI data """

    if data.operationId is None:
        return ParseError(data=data, detail="Path operations with operationId are not yet supported")

    endpoint = Endpoint(
        path=path,
        method=method,
        description=data.description,
        name=data.operationId,
        requires_security=bool(data.security),
        tag=tag,
    )

    result = Endpoint._add_parameters(endpoint, data)
    if isinstance(result, ParseError):
        return result
    result = Endpoint._add_responses(result, data.responses)
    if isinstance(result, ParseError):
        return result
    result = Endpoint._add_body(result, data)

    return result

async def act(self, ctx, *, target: Union[discord.Member, str] = None):
    """
    Acts on the specified user.
    """
    if not target or isinstance(target, str):
        return  # no help text

    try:
        if not ctx.guild:
            raise KeyError()
        message = await self.config.guild(ctx.guild).get_raw("custom", ctx.invoked_with)
    except KeyError:
        try:
            message = await self.config.get_raw("custom", ctx.invoked_with)
        except KeyError:
            message = NotImplemented

    if message is None:  # ignored command
        return
    elif message is NotImplemented:  # default
        # humanize action text
        action = inflection.humanize(ctx.invoked_with).split()
        iverb = -1

        for cycle in range(2):
            if iverb > -1:
                break
            for i, act in enumerate(action):
                act = act.lower()
                if (
                    act in NOLY_ADV
                    or act in CONJ
                    or (act.endswith("ly") and act not in LY_VERBS)
                    or (not cycle and act in SOFT_VERBS)
                ):
                    continue
                action[i] = inflection.pluralize(action[i])
                iverb = max(iverb, i)

        if iverb < 0:
            return
        action.insert(iverb + 1, target.mention)
        message = italics(" ".join(action))
    else:
        message = message.format(target, user=target)

    # add reaction gif
    if self.try_after and ctx.message.created_at < self.try_after:
        return await ctx.send(message)
    if not await ctx.embed_requested():
        return await ctx.send(message)
    key = (await ctx.bot.get_shared_api_tokens("tenor")).get("api_key")
    if not key:
        return await ctx.send(message)

def post(self, request, *args, **kwargs):
    serializer = self.serializer_class(data=request.data, context={'request': request})
    serializer.is_valid(raise_exception=True)
    user = serializer.validated_data['user']
    if user is None:
        return FormattedResponse(status=HTTP_401_UNAUTHORIZED, d={'reason': 'login_failed'}, m='login_failed')

    if not user.has_2fa():
        return FormattedResponse(status=HTTP_401_UNAUTHORIZED, d={'reason': '2fa_not_enabled'}, m='2fa_not_enabled')

    token = serializer.data['tfa']

    if len(token) == 6:
        if user.totp_device is not None and user.totp_device.validate_token(token):
            return self.issue_token(user)
    elif len(token) == 8:
        for code in user.backup_codes:
            if token == code.code:
                code.delete()
                return self.issue_token(user)

    return self.issue_token(user)

def parse_osc_99(raw: str) -> NotificationCommand:
    cmd = NotificationCommand()
    metadata, payload = raw.partition(';')[::2]
    payload_is_encoded = False
    payload_type = 'title'
    if metadata:
        for part in metadata.split(':'):
            try:
                k, v = part.split('=', 1)
            except Exception:
                log_error('Malformed OSC 99: metadata is not key=value pairs')
                return cmd
            if k == 'p':
                payload_type = v
            elif k == 'i':
                cmd.identifier = v
            elif k == 'e':
                payload_is_encoded = v == '1'
            elif k == 'd':
                cmd.done = v != '0'
            elif k == 'a':
                cmd.actions += f',{v}'
    if payload_type not in ('body', 'title'):
        log_error(f'Malformed OSC 99: unknown payload type: {payload_type}')
        return NotificationCommand()
    if payload_is_encoded:
        try:
            payload = standard_b64decode(payload).decode('utf-8')
        except Exception:
            log_error('Malformed OSC 99: payload is not base64 encoded UTF-8 text')
            return NotificationCommand()
    if payload_type == 'title':
        cmd.title = payload
    else:
        cmd.body = payload
    return cmd

def parse_headers(
    self, lines: List[bytes]
) -> Tuple["CIMultiDictProxy[str]", RawHeaders]:
    headers: CIMultiDict[str] = CIMultiDict()
    raw_headers = []

    lines_idx = 1
    line = lines[1]
    line_count = len(lines)

    while line:
        # Parse initial header name : value pair.
        try:
            bname, bvalue = line.split(b":", 1)
        except ValueError:
            raise InvalidHeader(line) from None

        # https://www.rfc-editor.org/rfc/rfc9112.html#section-5.1-2
        if {bname[0], bname[-1]} & {32, 9}:  # {" ", "\t"}
            raise InvalidHeader(line)

        bvalue = bvalue.lstrip(b" \t")
        if HDRRE.search(bname):
            raise InvalidHeader(bname)
        if len(bname) > self.max_field_size:
            raise LineTooLong(
                "request header name {}".format(
                    bname.decode("utf8", "backslashreplace")
                ),
                str(self.max_field_size),
                str(len(bname)),
            )

        header_length = len(bvalue)

        # next line
        lines_idx += 1
        line = lines[lines_idx]

        # consume continuation lines
        continuation = line and line[0] in (32, 9)  # (' ', '\t')

        # Deprecated: https://www.rfc-editor.org/rfc/rfc9112.html#name-obsolete-line-folding
        if continuation:
            bvalue_lst = [bvalue]
            while continuation:
                header_length += len(line)
                if header_length > self.max_field_size:
                    raise LineTooLong(
                        "request header field {}".format(
                            bname.decode("utf8", "backslashreplace")
                        ),
                        str(self.max_field_size),
                        str(header_length),

