def __call__(self, environ, start_response):
        req = Request(environ)
        if self.add_slash:
            url = req.path_url
            url += '/'
            if req.environ.get('QUERY_STRING'):
                url += '?' + req.environ['QUERY_STRING']
            self.location = url
        self.location = urlparse.urljoin(req.path_url, self.location)
        return super(_HTTPMove, self).__call__(
            environ, start_response)

async def close(self) -> None:
        """Signal the background task to shut down and wait for it."""
        self.stop_event.set()
        try:
            await asyncio.wait_for(self.task, timeout=_CLOSE_TIMEOUT)
        except asyncio.TimeoutError:
            logger.warning(
                "MCP session %r did not shut down within %.1fs — cancelling",
                self.name,
                _CLOSE_TIMEOUT,
            )
            self.task.cancel()
            try:
                await self.task
            except BaseException:
                pass
        except asyncio.CancelledError:
            pass
        except BaseException:
            logger.debug("Error while closing MCP session %r", self.name, exc_info=True)

