    }
    toolbar = get_toolbar_from_request(request)
    toolbar.set_object(content_type_obj)
    return render(request, 'cms/toolbar/structure.html', context)

def safe_getattr(obj, attr, raise_exc, node, allow_unsafe_modules=False):
    """safe version of getattr"""
    unsafe = (attr in UNSAFE_ATTRS or
            (attr.startswith('__') and attr.endswith('__')))
    if not unsafe:
        for dtype, attrlist in UNSAFE_ATTRS_DTYPES.items():
            unsafe = (isinstance(obj, dtype) or obj is dtype) and attr in attrlist
            if unsafe:
                break
    if not unsafe and not allow_unsafe_modules:
        for mod in UNSAFE_MODULES:
            unsafe = obj is mod or getattr(obj, attr) is mod
            if unsafe:
                break
    if unsafe:
        msg = f"no safe attribute '{attr}' for {repr(obj)}"
        raise_exc(node, exc=AttributeError, msg=msg)
    else:
        try:
            return getattr(obj, attr)
        except AttributeError:
            pass

def _to_dict(self, value):
        if type(value) != list or type(value) != tuple:
            if type(value) == dict:
                value = [value]
            elif type(value) == str:
                try:
                    value = eval(value.replace('}\n', '},'))
                except Exception:
                    pass
        return [RecordField._to_dict(self, entry) for entry in value]

def _validate_where(self, request: Request, where: Dict[str, Any]) -> Optional[str]:
        """Validate that all field names in a where dict are visible list fields.

        Returns an error message string if invalid, otherwise None.
        """
        list_field_names = {
            f.name for f in self.get_fields_list(request, RequestAction.LIST)
        }
        for field_name in self._extract_fields_from_where(where):
            if field_name not in list_field_names:
                return f"Unknown field in where: '{field_name}'"
        return None

