def render_object_structure(request, content_type_id, object_id):
    try:
        content_type = ContentType.objects.get_for_id(content_type_id)
    except ContentType.DoesNotExist as err:
        raise Http404 from err

    try:
        if issubclass(content_type.model_class(), PageContent):
            content_type_obj = PageContent._base_manager.select_related("page").get(pk=object_id)
            request.current_page = content_type_obj.page
        else:
            content_type_obj = content_type.get_object_for_this_type(pk=object_id)
    except ObjectDoesNotExist as err:
        raise Http404 from err

    context = {
        'object': content_type_obj,
        'cms_toolbar': request.toolbar,
    }
    toolbar = get_toolbar_from_request(request)
    toolbar.set_object(content_type_obj)
    return render(request, 'cms/toolbar/structure.html', context)

def raise_exception(self, node, exc=None, msg='', expr=None, lineno=None):
        """Add an exception."""
        if expr is not None:
            self.expr = expr

        msg = str(msg)
        text = self.expr
        if len(self.code_text) > 0:
            text = self.code_text[-1]
        err = ExceptionHolder(node, exc=exc, msg=msg, expr=self.expr,
                             text=text, lineno=lineno)
        self._interrupt = ast.Raise()

        self.error.append(err)
        if self.error_msg is None:
            self.error_msg = msg
        elif len(msg) > 0:
            pass
            # if err.exc is not None:
            #     self.error_msg = f"{err.exc.__name__}: {msg}"
        if exc is None:
            exc = self.error[-1].exc
            if exc is None and len(self.error) > 0:
                while exc is None and len(self.error) > 0:
                    err = self.error.pop()
                    exc = err.exc

        if exc is None:
            exc = Exception
        if len(err.msg) == 0 and len(self.error_msg) == 0 and len(self.error) > 1:
            err = self.error.pop(-1)
            raise err.exc(err.msg)
        else:
            if len(err.msg) == 0:
                err.msg = self.error_msg
            raise exc(self.error_msg)

