def components(self, request: Request, **kwargs):
        obj = self.get_object()
        self.perm_check(request, obj)
        if "component_id" not in request.data:
            msg = "Missing component_id parameter"
            raise ValidationError({"component_id": msg})

        field_name = "component_id"
        try:
            component = Component.objects.filter_access(request.user).get(
                pk=int(request.data[field_name])
            )
        except (TypeError, ValueError) as error:
            raise invalid_integer_error(field_name) from error
        except Component.DoesNotExist as error:
            raise not_found_validation_error(field_name, "Component") from error
        obj.components.add(component)
        serializer = self.serializer_class(obj, context={"request": request})

        return Response(serializer.data, status=HTTP_200_OK)

def needs_project_filter(self):
        if self.is_superuser:
            return False
        if self.project_permissions[-SELECTION_ALL]:
            return False
        return Project.objects.exclude(
            pk__in=self.allowed_projects.values("pk").order_by()
        ).exists()

def _get_responses_by_components(
        self, has_bycomps: TypeWithByComps, write_empty_responses: bool
    ) -> Dict[str, Tuple[str, List[str], str]]:
        """Get response per component, substitute component id with title if possible."""
        response_per_component: Dict[str, Tuple[str, str]] = {}
        for by_comp in as_list(has_bycomps.by_components):  # type: ignore
            # look up component title
            subheader = by_comp.component_uuid
            prose = ''
            status = ''
            rules = []
            if self._ssp.system_implementation.components:
                for comp in self._ssp.system_implementation.components:
                    if comp.uuid == by_comp.component_uuid:
                        title = comp.title
                        if title:
                            subheader = title
            if by_comp.description:
                prose = by_comp.description
            if by_comp.implementation_status:
                status = by_comp.implementation_status.state
            rules, _ = ControlInterface.get_rule_list_for_item(by_comp)

            if prose or write_empty_responses:
                if subheader:
                    response_per_component[subheader] = (prose, rules, status)

        return response_per_component

